export function ModulateDmgByType2(multiplier: any, move: any, flags: any): any {
  gBattleMoveDamage = gBattleMoveDamage * multiplier / 10;
      if (gBattleMoveDamage == 0 && multiplier != 0)
          gBattleMoveDamage = 1;

      switch (multiplier)
      {
      case (0):
          flags |= ((1 << 3));
          flags &= ~((1 << 2));
          flags &= ~((1 << 1));
          break;
      case (5):
          if (gBattleMoves[move].power && !(flags & ((((1 << 0)) | ((1 << 3)) | ((1 << 5))))))
          {
              if (flags & ((1 << 1)))
                  flags &= ~((1 << 1));
              else
                  flags |= ((1 << 2));
          }
          break;
      case (20):
          if (gBattleMoves[move].power && !(flags & ((((1 << 0)) | ((1 << 3)) | ((1 << 5))))))
          {
              if (flags & ((1 << 2)))
                  flags &= ~((1 << 2));
              else
                  flags |= ((1 << 1));
          }
          break;
      }
}

/** u8 TypeCalc(u16 move, u8 attacker, u8 defender) */
export function TypeCalc(move: any, attacker: any, defender: any): any {
  let i: any = 0;
      let flags: any = 0;
      let moveType: any = null;

      if (move == (165))
          return 0;

      moveType = gBattleMoves[move].type;

       
      if (IS_BATTLER_OF_TYPE(attacker, moveType))
      {
          gBattleMoveDamage = gBattleMoveDamage * 15;
          gBattleMoveDamage = gBattleMoveDamage / 10;
      }

      if (gBattleMons[defender].ability == (26) && moveType == (4))
      {
          flags |= (((1 << 0)) | ((1 << 3)));
      }
      else
      {
          while (TYPE_EFFECT_ATK_TYPE(i) != (0xFF))
          {
              if (TYPE_EFFECT_ATK_TYPE(i) == (0xFE))
              {
                  if (gBattleMons[defender].status2 & ((1 << 29)))
                      break;
                  i += 3;
                  continue;
              }

              else if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
              {
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[defender].types[0])
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == gBattleMons[defender].types[1] &&
                      gBattleMons[defender].types[0] != gBattleMons[defender].types[1])
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
              }
              i += 3;
          }
      }

      if (gBattleMons[defender].ability == (25) && !(flags & ((1 << 0)))
          && AttacksThisTurn(attacker, move) == 2
          && (!(flags & ((1 << 1))) || ((flags & (((1 << 1)) | ((1 << 2)))) == (((1 << 1)) | ((1 << 2)))))
          && gBattleMoves[move].power)
      {
          flags |= ((1 << 0));
      }
      return flags;
}

/** u8 AI_TypeCalc(u16 move, u16 targetSpecies, u8 targetAbility) */
export function AI_TypeCalc(move: any, targetSpecies: any, targetAbility: any): any {
  let i: any = 0;
      let flags: any = 0;
      let type1: any = gSpeciesInfo[targetSpecies].types[0], type2 = gSpeciesInfo[targetSpecies].types[1];
      let moveType: any = null;

      if (move == (165))
          return 0;

      moveType = gBattleMoves[move].type;

      if (targetAbility == (26) && moveType == (4))
      {
          flags = ((1 << 0)) | ((1 << 3));
      }
      else
      {
          while (TYPE_EFFECT_ATK_TYPE(i) != (0xFF))
          {
              if (TYPE_EFFECT_ATK_TYPE(i) == (0xFE))
              {
                  i += 3;
                  continue;
              }
              if (TYPE_EFFECT_ATK_TYPE(i) == moveType)
              {
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == type1)
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
                   
                  if (TYPE_EFFECT_DEF_TYPE(i) == type2 && type1 != type2)
                      ModulateDmgByType2(TYPE_EFFECT_MULTIPLIER(i), move,flags);
              }
              i += 3;
          }
      }
      if (targetAbility == (25)
       && (!(flags & ((1 << 1))) || ((flags & (((1 << 1)) | ((1 << 2)))) == (((1 << 1)) | ((1 << 2)))))
       && gBattleMoves[move].power)
          flags |= ((1 << 3));
      return flags;
}

/** static inline void ApplyRandomDmgMultiplier(void) */
export function ApplyRandomDmgMultiplier(): any {
  let rand: any = Random();
      let randPercent: any = 100 - (rand % 16);

      if (gBattleMoveDamage != 0)
      {
          gBattleMoveDamage *= randPercent;
          gBattleMoveDamage /= 100;
          if (gBattleMoveDamage == 0)
              gBattleMoveDamage = 1;
      }
}

