/** static void Cmd_jumpifstat(void) */
export function Cmd_jumpifstat(): any {
  let ret: any = 0;
      let battler: any = GetBattlerForBattleScript(gBattlescriptCurrInstr[1]);
      let value: any = gBattleMons[battler].statStages[gBattlescriptCurrInstr[3]];

      switch (gBattlescriptCurrInstr[2])
      {
      case (0):
          if (value == gBattlescriptCurrInstr[4])
              ret++;
          break;
      case (1):
          if (value != gBattlescriptCurrInstr[4])
              ret++;
          break;
      case (2):
          if (value > gBattlescriptCurrInstr[4])
              ret++;
          break;
      case (3):
          if (value < gBattlescriptCurrInstr[4])
              ret++;
          break;
      case (4):
          if (value & gBattlescriptCurrInstr[4])
              ret++;
          break;
      case (5):
          if (!(value & gBattlescriptCurrInstr[4]))
              ret++;
          break;
      }

      if (ret)
          gBattlescriptCurrInstr = T2_READ_PTR(gBattlescriptCurrInstr + 5);
      else
          gBattlescriptCurrInstr += 9;
}

