/** static void Cmd_hiddenpowercalc(void) */
export function Cmd_hiddenpowercalc(): any {
  let powerBits: any = ((gBattleMons[gBattlerAttacker].hpIV & 2) >> 1)
                   | ((gBattleMons[gBattlerAttacker].attackIV & 2) << 0)
                   | ((gBattleMons[gBattlerAttacker].defenseIV & 2) << 1)
                   | ((gBattleMons[gBattlerAttacker].speedIV & 2) << 2)
                   | ((gBattleMons[gBattlerAttacker].spAttackIV & 2) << 3)
                   | ((gBattleMons[gBattlerAttacker].spDefenseIV & 2) << 4);

      let typeBits: any = ((gBattleMons[gBattlerAttacker].hpIV & 1) << 0)
                   | ((gBattleMons[gBattlerAttacker].attackIV & 1) << 1)
                   | ((gBattleMons[gBattlerAttacker].defenseIV & 1) << 2)
                   | ((gBattleMons[gBattlerAttacker].speedIV & 1) << 3)
                   | ((gBattleMons[gBattlerAttacker].spAttackIV & 1) << 4)
                   | ((gBattleMons[gBattlerAttacker].spDefenseIV & 1) << 5);

      gDynamicBasePower = (40 * powerBits) / 63 + 30;

       
       
      gBattleStruct.dynamicMoveType = (((18) - 3) * typeBits) / 63 + 1;
      if (gBattleStruct.dynamicMoveType >= (9))
          gBattleStruct.dynamicMoveType++;
      gBattleStruct.dynamicMoveType |= ((1 << 6)) | ((1 << 7));

      gBattlescriptCurrInstr++;
}

