/** static void Cmd_tryswapitems(void) */
export function Cmd_tryswapitems(): any {
  if (gBattleTypeFlags & ((1 << 26))
          || (GetBattlerSide(gBattlerAttacker) == (1)
              && !(gBattleTypeFlags & (((1 << 1))
                                    | ((1 << 11))
                                    | BATTLE_TYPE_FRONTIER
                                    | ((1 << 27))
                                    | ((1 << 25))))))
      {
          gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
      }
      else
      {
          let sideAttacker: any = GetBattlerSide(gBattlerAttacker);
          let sideTarget: any = GetBattlerSide(gBattlerTarget);

           
          if (!(gBattleTypeFlags & (((1 << 1))
                               | ((1 << 11))
                               | BATTLE_TYPE_FRONTIER
                               | ((1 << 27))
                               | ((1 << 25))))
              && (gWishFutureKnock.knockedOffMons[sideAttacker] & gBitTable[gBattlerPartyIndexes[gBattlerAttacker]]
                  || gWishFutureKnock.knockedOffMons[sideTarget] & gBitTable[gBattlerPartyIndexes[gBattlerTarget]]))
          {
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          }
           
           
          else if ((gBattleMons[gBattlerAttacker].item == (0) && gBattleMons[gBattlerTarget].item == (0))
                   || gBattleMons[gBattlerAttacker].item == (175)
                   || gBattleMons[gBattlerTarget].item == (175)
                   || IS_ITEM_MAIL(gBattleMons[gBattlerAttacker].item)
                   || IS_ITEM_MAIL(gBattleMons[gBattlerTarget].item))
          {
              gBattlescriptCurrInstr = T1_READ_PTR(gBattlescriptCurrInstr + 1);
          }
           
          else if (gBattleMons[gBattlerTarget].ability == (60))
          {
              gBattlescriptCurrInstr = BattleScript_StickyHoldActivates;
              gLastUsedAbility = gBattleMons[gBattlerTarget].ability;
              RecordAbilityBattle(gBattlerTarget, gLastUsedAbility);
          }
           
          else
          {
              let oldItemAtk, newItemAtk;

              newItemAtk =gBattleStruct.changedItems[gBattlerAttacker];
              oldItemAtk = gBattleMons[gBattlerAttacker].item;
              newItemAtk = gBattleMons[gBattlerTarget].item;

              gBattleMons[gBattlerAttacker].item = (0);
              gBattleMons[gBattlerTarget].item = oldItemAtk;

              gActiveBattler = gBattlerAttacker;
              BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_HELDITEM_BATTLE, 0, 0, newItemAtk);
              MarkBattlerForControllerExec(gBattlerAttacker);

              gActiveBattler = gBattlerTarget;
              BtlController_EmitSetMonData(B_COMM_TO_CONTROLLER, REQUEST_HELDITEM_BATTLE, 0, sizeof(gBattleMons[gBattlerTarget].item),gBattleMons[gBattlerTarget].item);
              MarkBattlerForControllerExec(gBattlerTarget);

              /* transpiler bug LHS : ((gBattleStruct.choicedMove[gBattlerTarget]) + 0) = 0; */ ;
              /* transpiler bug LHS : ((gBattleStruct.choicedMove[gBattlerTarget]) + 1) = 0; */ ;

              /* transpiler bug LHS : ((gBattleStruct.choicedMove[gBattlerAttacker]) + 0) = 0; */ ;
              /* transpiler bug LHS : ((gBattleStruct.choicedMove[gBattlerAttacker]) + 1) = 0; */ ;

              gBattlescriptCurrInstr += 5;

              PREPARE_ITEM_BUFFER(gBattleTextBuff1, newItemAtk)
              PREPARE_ITEM_BUFFER(gBattleTextBuff2, oldItemAtk)

              if (oldItemAtk != (0) && newItemAtk != (0))
                  gBattleCommunication[(5)] = (2);   
              else if (oldItemAtk == (0) && newItemAtk != (0))
                  gBattleCommunication[(5)] = (0);  
              else
                  gBattleCommunication[(5)] = (1);  
          }
      }
}

