/** void HandleBattleWindow(u8 xStart, u8 yStart, u8 xEnd, u8 yEnd, u8 flags) */
export function HandleBattleWindow(xStart: any, yStart: any, xEnd: any, yEnd: any, flags: any): any {
  let destY, destX;
      let _var: any = 0;

      for (destY = yStart; destY <= yEnd; destY++)
      {
          for (destX = xStart; destX <= xEnd; destX++)
          {
              if (destY == yStart)
              {
                  if (destX == xStart)
                      _var = 0x1022;
                  else if (destX == xEnd)
                      _var = 0x1024;
                  else
                      _var = 0x1023;
              }
              else if (destY == yEnd)
              {
                  if (destX == xStart)
                      _var = 0x1028;
                  else if (destX == xEnd)
                      _var = 0x102A;
                  else
                      _var = 0x1029;
              }
              else
              {
                  if (destX == xStart)
                      _var = 0x1025;
                  else if (destX == xEnd)
                      _var = 0x1027;
                  else
                      _var = 0x1026;
              }

              if (flags & ((1 << 0)))
                  _var = 0;

              if (flags & ((1 << 7)))
                  CopyToBgTilemapBufferRect_ChangePalette(1,_var, destX, destY, 1, 1, 0x11);
              else
                  CopyToBgTilemapBufferRect_ChangePalette(0,_var, destX, destY, 1, 1, 0x11);
          }
      }
}

